    translate([-(block_length_mm/2 - chamfer_mm/2),  block_width_mm/2 - chamfer_mm/2, 0])
      cube([chamfer_mm, chamfer_mm, block_height_mm + 2*overlap_mm], center=true);
    translate([-(block_length_mm/2 - chamfer_mm/2), -(block_width_mm/2 - chamfer_mm/2), 0])
