module rotor_can() {
    // Hollow can (shell) around stator
    difference() {
        cylinder(r=rotor_outer_r, h=rotor_height_mm, center=true);
        cylinder(r=rotor_inner_r_clamped, h=rotor_height_mm + 2*overlap_mm, center=true);
