        for (i = [0:num_stator_teeth-1]) {
            rotate([0,0,i*360/num_stator_teeth])
                translate([stator_r + tooth_depth/2 - overlap, 0, 0])
                    cube([tooth_depth, tooth_width, stator_height], center=true);
