        translate([impeller_outer_diameter/2-3,3,0]) rotate([0,12,20]) cylinder(r=2.5, h=5, $fn=8);
      }
  }
}

// Blower Fan module
module blower_fan() {
  blower();
  translate([0, 0, overall_depth/2 + 5]) fan();
}

// Assembly module
module assembly() {
  blower_fan();
}

assembly();

