    conn_y = -(overall_height_mm/2 - pcb_inset_mm - conn_h/2 - 1.2);
    translate([0, conn_y,
               z_pcb_center + pcb_thickness_mm/2 + conn_t/2 - eps])
      rrect3d(conn_w, conn_h, conn_t, 0.6);

