    ffc_y_center = -(overall_height_mm/2 + ffc_l_mm/2 - eps);
    translate([0, ffc_y_center,
               z_pcb_center + pcb_thickness_mm/2 + ffc_t_mm/2 - eps])
      rrect3d(ffc_w_mm, ffc_l_mm, ffc_t_mm, 0.4);
  }
}

module bezel_with_window(){
