    // Creates a shallow inset panel area around the screen/buttons.
    inset_t = 0.6;
    translate([0, 0, bezel_thickness_mm/2 - inset_t/2])
      rrect3d(bezel_width_mm - 2.0, bezel_height_mm - 2.0,
              inset_t + 2*overlap_mm, 1.6);
  }
}

// Render
pzem001_solid();

