module rrect2d(w, h, r) {
  rr = min(r, min(w, h)/2);
  hull() {
    for (sx = [-1, 1], sy = [-1, 1])
      translate([sx*(w/2 - rr), sy*(h/2 - rr)]) circle(r=rr);
  }
}

module rrect3d(w, h, t, r) {
  linear_extrude(height=t, center=true) rrect2d(w, h, r);
