  glass_w = max(1, display_w - 2*lcd_aperture_inset);
  glass_h = max(1, display_h - 2*lcd_aperture_inset);
  glass_zc = bezel_front_z - (display_recess_depth + lcd_aperture_depth)/2 + overlap*0.2;

