      rrect3d(glass_w, glass_h, (display_recess_depth + lcd_aperture_depth) + 2*overlap, max(0.6, display_r-0.4));

    // Small indicator notch under display (subtle cue)
    notch_w = display_w*0.22;
    notch_h = display_h*0.18;
