module mounting_holes() {
    for (sx = [-1, 1], sy = [-1, 1])
        translate([sx*(pcb_L/2 - hole_edge_offset), sy*(pcb_W/2 - hole_edge_offset), 0])
            cylinder(h = pcb_T + 2*hole_overlap, r = hole_d/2, center = true);
