// ---------- Helper modules ----------
module rounded_plate(L, W, T, r) {
    // Rounded rectangle prism via hull of corner cylinders
    hull() {
        for (sx = [-1, 1], sy = [-1, 1])
            translate([sx*(L/2 - r), sy*(W/2 - r), 0])
                cylinder(r=r, h=T, center=true);
