            // Small "chip" near back-left
            translate([x_left + board_length*0.30,
                       y_back - board_width*0.25,
                       pcb_top_z + 2.0/2 - comp_clear])
                color([0.2,0.2,0.2])
                    box_centered([10, 8, 2.0]);
