    // size_xyz = [width_x, protrusion_y, height_z]
    y_in = size_xyz[1]/2 - ov;
    y_edge = pcb_width/2;
    y_pos = (end=="top")
        ? (y_edge + y_in)
        : (-y_edge - y_in);

    translate([x, y_pos, pcb_thickness/2 + size_xyz[2]/2 - ov])
