        smd_h = 1.2;
        smd_l = 3.2;
        smd_w = 1.6;

        for (dx = [-1, 0, 1], dy = [-1, 1]) {
            translate([dx*6.0, dy*8.0, 0])
                place_on_top(pcb_top_z, smd_h)
                    cube([smd_l, smd_w, smd_h], center=true);
        }
    }
}

