    color([0.0, 0.4, 0.2])
        linear_extrude(height=thickness, center=false, convexity=10)
            rounded_rect_2d(length, width, corner_radius);
}

// Place PCB so it spans z=[0..thickness] (avoids any center/preview edge cases)
translate([0, 0, 0])
    pcb_plate();

