        // housing side face at x = side*(housing_length_x_mm/2)
        // insert center x = side*(housing_length_x_mm/2 + insert_thickness/2 - overlap)
        xc = side*(housing_length_x_mm/2 + side_insert_thickness_x_mm/2 - overlap_mm);

