// Potentiometer - complete geometry
module potentiometer() {
  color("DimGray") {
    // Body with rounded corners
    minkowski() {
      translate([0, 0, 0])
        cube([body_width - 2*corner_radius, body_depth - 2*corner_radius, body_height], center=true);
      sphere(r=corner_radius, center=true);
    }

    // Boss
