// -------- Helpers --------
function clamp(x, a, b) = x < a ? a : (x > b ? b : x);

module hex_prism(af, h, center=false) {
    // Regular hex with given across-flats
    r = (af/2)/cos(30);
    cylinder(r=r, h=h, center=center, $fn=6);
