hex_socket_depth_mm  = 2.0;

// Thread appearance controls (simple helical ridge; not a standards-accurate ISO profile)
thread_pitch_mm   = 0.8;     // M5 coarse pitch
thread_depth_mm   = 0.35;    // radial height of ridge (visual)
