    skirt_h = max(0.6, h_head * 0.45);
    dome_h  = h_head - skirt_h;

    // Sphere radius that yields a spherical cap of height dome_h on base radius r_head:
    // R = (a^2 + h^2) / (2h)
    R = (r_head*r_head + dome_h*dome_h) / (2*dome_h);

