        if (thread_h > 0) {
            translate([0,0,-shank_len + thread_end_mm])
                linear_extrude(
                    height=thread_h,
                    twist=360 * (thread_h / thread_pitch_mm),
                    slices=max(20, ceil(thread_h*12)),
                    convexity=10
                )
                translate([r_shaft - thread_depth_mm*0.2, 0, 0])
                    circle(r=thread_depth_mm, $fn=thread_fn);
