    turns = len / pitch;

    // Build a helical "rib" by twisting a small triangular profile.
    // Use an XY profile located at the correct radius; extrude along Z with twist.
    linear_extrude(
        height = len,
        twist = 360 * turns,
        slices = max(ceil(turns * 32), 32),
        convexity = 10
