      translate([0, 0, z_pilot])
        cylinder(r=pilot_diameter_mm/2, h=pilot_depth_mm, center=true);

      // Output Shaft
      translate([0, 0, z_shaft])
        cylinder(r=shaft_diameter_mm/2, h=shaft_length_mm, center=true);

