    // Short edges (along X), cutters placed at +/-Y faces
    for (sy = [-1, 1])
        translate([0, sy*(sheet_W/2 - chamfer_C/2), 0])
            rotate([45, 0, 0])
                cube([sheet_L + 2*overlap, chamfer_C, sheet_T + 2*overlap], center=true);
