}

module mounting_holes() {
  union() {
    mount_hole(sheet_length/2 - mount_hole_edge_offset, sheet_width/2 - mount_hole_edge_offset);
    mount_hole(-sheet_length/2 + mount_hole_edge_offset, sheet_width/2 - mount_hole_edge_offset);
