include_toggle_lever = 1; //[0:1:1]
include_terminals    = 1; //[0:1:1]

eps_mm = 0.8; //[0.2:2:0.1]

// Detail parameters (kept proportional; do not change body dims)
face_thickness_mm = 0.6; //[0.3:1.2:0.1]

