toggle_lever_height_mm   = 10;  //[5:20:0.5]
lever_tip_d_mm           = 3.2; // knob at end

// Mounting bushing + hex nut (stylized)
bushing_d_mm = 4.2;
bushing_h_mm = 2.2;
nut_flat_mm  = 6.2;  // across flats
nut_h_mm     = 1.6;

