body_height_mm   = 13.1; //[6.55:26.2:0.1]

include_toggle_lever = 1; //[0:1:1]
include_terminals    = 1; //[0:1:1]

collar_diameter_mm   = 14.0; //[7.0:28.0:0.1]
collar_thickness_mm  = 2.0;  //[1.0:4.0:0.1]

